const char* phraseText(uint16_t msgIndex) {
    int lo = 0, hi = kNumPhrases - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (kPhrases[mid].msgIndex == msgIndex) return kPhrases[mid].text;
        if (kPhrases[mid].msgIndex < msgIndex) lo = mid + 1;
        else hi = mid - 1;
    }
    return nullptr;
}

